def max_window_sum(nums: list[int], k: int) -> int | None:
    if not nums or k > len(nums):
        return None

    current_sum = sum(nums[:k])
    max_sum = current_sum

    for i in range(k, len(nums)):
        current_sum += nums[i] - nums[i - k]
        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum
